css:
br {
    line-height:5px;
}

.text-center {
    text-align: center;
    vertical-align: middle;
}

.e-invoice-table tr:nth-child(odd) {
    background-color: #f2f2f2;
}

.e-invoice-table tr:nth-child(even) {
    background-color: #ffffff;
}

.e-invoice-table td{
vertical-align:middle !important;
}
.e-invoice-table th{
    background-color: #ffffff;
}

.payment_terms_table th, .payment_terms_table td{
    word-wrap: break-word;
    white-space: normal;
    text-overflow: ellipsis;
}


.print-heading{
    border-bottom:1px solid #000;
    margin-bottom:1mm;
    color:#000;
    font-weight:bold;
}

.einv-det .col-xs-7{
    height:100%;
}

/* No fixed margin-top: wkhtmltopdf sizes the top margin to the header. 2mm sides
   (also the wkhtmltopdf side margins) as in SI V2. */
.print-format {
    margin-left: 2mm;
    margin-right: 2mm;
}

.print-format .row:not(.section-break) {
    margin-top: 0px !important;
}

.section-heading {
    margin-top: 3px;
    margin-bottom: 0px;
    font-weight: bold;
}

.party-details-table {
    table-layout: fixed;
    width: 100%;
}
.party-details-table td {
    vertical-align: top;
    padding: 8px;
}


.print-format h6{
    font-weight: bold;
    margin-top:0px;
    margin-bottom:0px;
}

.e-invoice-table {
    /*margin: 5px 0;*/
}

.item-det{
    padding:0px !important;
    font-size:0.8em;
    height:100%;
    width:100%;
}

table.table {
    border: 1px solid #000 !important;
    margin: 0;
    width: 100%;
}

.e-invoice-table th,
        .e-invoice-table td{
            text-align:center !important;
        }
.e-invoice-table th{
    font-weight:bold;
}
.e-invoice-table{
    padding:0;

    table-layout: fixed;
}

table td, table th {
    border: 1px solid #000 !important;
    white-space: normal;
    word-wrap: break-word;
}
.print-format td, .print-format th{
    padding:1px !important;
}

.qrcode {
    width: 125px;
}

.no-preview-available {
    color: grey;
    font-size: 14px;
}

.wrap-text {
    white-space: pre-wrap
}

.einv-det .col-xs-7.column-break.text-right {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 100%;
    font-size:10px;
}

.einv-det .col-xs-7.column-break.text-right .row.data-field {
    display: flex;
    align-items: center; 
    height: 100%;
    padding: 0;
    flex: 1; 
}

.einv-det .col-xs-7.column-break.text-right .row.data-field label, 
.einv-det .col-xs-7.column-break.text-right .row.data-field .value {
    padding: 2px;
    flex: 1; 
}
.print-format,table{
    font-size:0.7rem;
}

.watermark {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-45deg);
    -webkit-transform:translate(-50%, -50%) rotate(-45deg);
    opacity: 0.075;
    font-size: 50px;
    color: #000;
    z-index: 1000;
    white-space: normal;
    pointer-events: none; 
}


#header-html {
    position: static;
    top: 0;
}
#footer-html{
    position: static;
    bottom: 0;
}

.page{
    /*background:rgba(0,0,0,0.1);*/
    /*padding:0 10px 0 10px;*/
    margin:0 0 0 0;
    padding:0 0 0 0;
}

.main-content {
    box-sizing: border-box;
    /*page-break-after: always;*/
}
.page-number {
    content: counter(page);
}

.no-break {
        page-break-inside: avoid;
    }









.borderless,
.borderless th,
.borderless td {
    border: none !important;
}

.print-format table td img.barcode,
.print-format table td img.qr-code {
    margin-top: 5px;
    width: 95px !important;
    image-rendering: -webkit-optimize-contrast;
}
.vehicle-info {
    margin: 0 !important;
    font-size: 9px;
    border-collapse: collapse;
}
.vehicle-info th {
    font-weight: bold;
}
.section-separator {
    border-top: 2px solid #bbb;
    margin: 8px 0 16px;
}
.ewb-no-span {
    font-size: 13px;
}
.vehicle-info td,
.vehicle-info th {
    border: 0 !important;
    border-top: 1px solid black !important;
}
.e-waybill-number {
    font-size: 16px;
}
h1.title {
    font-size: 18px;
    font-weight: bold;
    margin: 0;
}

tbody>tr>td,
tbody>tr>th {
    padding: 6px !important;
    border-top: none;
    color: black;
}

.ewaybill-page-layout {
    font-size: 12px;
    line-height: 1.4286;
    box-sizing: border-box;
    transform-origin: top center;
    width: 95%;
    margin: 0 auto;
}

/* PDF header page only (Frappe copies the header into .wrapper): cancel its 5mm bottom
   padding. In the on-screen/browser view the header is in the page flow, where
   a negative margin would slide the next block under the header rule. */
.wrapper > .print-heading {
    margin-top:-11mm;
    margin-bottom:-5mm;
}
/* PDF footer page: Frappe pads it 15mm on top. -8mm puts the footer ~5mm from the
   page edge without shrinking the page body (tested: -12mm floats it higher,
   -4mm and above take room from the body). */
.wrapper > .page-footer-1 {
    margin-top:-8mm;
}

/* Browser preview and browser printing: 5mm page margins (also the screen padding). */
@page {
  margin: 5mm;
}


/* Header: logo keeps its aspect ratio; invoice identity + IRP acknowledgement on the right. */
.bns-logo img {
  max-width: 100%;
  max-height: 30mm;
}
.bns-doc-title {
  margin: 0 0 1mm 0;
}
.bns-inv-id {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  margin-top: 1mm !important;
}
.bns-inv-id td {
  border: 1px solid #000 !important;
  padding: 1mm 1.5mm !important;
  text-align: left;
  vertical-align: top;
  white-space: nowrap;
}
.bns-inv-label {
  font-size: 7pt;
  font-weight: normal;
  color: #333;
}
.bns-inv-value {
  font-size: 9.5pt;
  font-weight: bold;
  line-height: 1.2;
}

/* Tally-style fill: empty rows continue the item columns down to the closing block. */
.item-det tr.bns-fill td {
  background-color: #fff !important;
  border-top: 0 !important;
}
.final-tax-total-table.bns-keep {
  page-break-inside: avoid;
}
/* Measuring-pass markers (never printed in the final PDF). */
.bns-mk {
  height: 0;
  overflow: visible;
  font-size: 4pt;
  line-height: 1;
  white-space: nowrap;
}
.bns-ruler {
  height: 3pt;
  font-size: 2pt;
  line-height: 3pt;
  overflow: hidden;
}

.bns-inv-small {
  font-size: 8pt;
  white-space: normal;
}
.page-footer-1 {
  border-top: 1px solid black;
  padding-top: 1mm;
}
.final-tax-total-table {
  margin-top: 2mm;
  width: 100%;
}
.final-tax-total-table > table,
.final-tax-total-table > div {
  page-break-inside: avoid;
}
.item-det tr {
  page-break-inside: avoid;
}
.item-det thead {
  display: table-header-group;
}
.party-details-table p,
.final-tax-total-table p {
  margin: 0;
}
.party-details-table td {
  padding: 2px 4px !important;
}
/* e-Waybill page: compact rows; stretched or scaled to one page by the fill plan. */
.ewaybill-page-layout td,
.ewaybill-page-layout th {
  padding: 2px 6px !important;
}
.ewaybill-page-layout .section-separator {
  margin: 2px 0;
}
.ewaybill-page-layout .ewb-details td {
  vertical-align: middle !important;
}

.bns-totals td.bns-words {
  vertical-align: top !important;
  text-align: left !important;
}
.final-tax-total-table .bns-terms td {
  text-align: left !important;
}
.final-tax-total-table .bns-terms ol,
.final-tax-total-table .bns-terms ul {
  margin: 0;
  padding-left: 5mm;
}
.final-tax-total-table .bns-terms li {
  line-height: 1.3;
}

/* Item cell, same as the Sales Invoice: name, then HSN/SAC and EAN in small italics. */
.item-det .item-det-item-name {
  text-align: left !important;
  padding-left: 1mm !important;
}
.item-det .item-det-item-name b {
  font-size: 1em;
}
.bns-item-sub {
  font-size: 0.8em;
  margin: 0;
}

/* Item table: one size across all BNS formats (a little bigger than before). */
.item-det td, .item-det th,
.item-det .item-det-item-name {
  font-size: 8.5pt !important;
}

/* Item rows: qty, rates and amounts at the item-table size (their inline rem sizes were tiny). */
.item-det tbody td,
.item-det tbody td b,
.item-det tbody td span,
.item-det tbody td p {
  font-size: 8.5pt !important;
}
.item-det tbody td small {
  font-size: 6.5pt !important;
}
.item-det tbody td p.bns-item-sub,
.item-det tbody td p.bns-item-sub b {
  font-size: 7pt !important;
}

/* Header matches the Sales Invoice: same text sizes, and pulled to the page top in the
   PDF (this template's ".print-format .row { margin-top: 0 !important }" would cancel
   the pull, so the selector here is stronger). */
.print-heading {
  font-size: 12px !important;
}
.print-heading h3 {
  font-size: 18px !important;
}
.print-format .wrapper > .row.print-heading {
  margin-top: -11mm !important;
  margin-bottom: -5mm !important;
}

/* Party table (buyer/supplier, transport) at the Sales Invoice's size. */
.party-details-table td,
.party-details-table td p,
.party-details-table td h6 {
  font-size: 12px !important;
}

/* Closing block (the Sales Invoice's): same text size as the invoice. */
.final-tax-total-table table {
  font-size: 12px !important;
}
.final-tax-total-table .bns-terms ol,
.final-tax-total-table .bns-terms ul {
  margin: 0;
  padding-left: 5mm;
}
.final-tax-total-table .bns-terms li {
  line-height: 1.3;
}

html:
{%- from "templates/print_formats/standard_macros.html" import add_header, render_field, print_value -%}

{% macro format_address(address) %}
{% if address %}
<p>
    {{ address.address_line1 }}
    {% if address.address_line2 %}
    {{ address.address_line2 }}<br>
    {% endif %}
    {{ address.city }}, {{ address.state }}, {{ address.country }}: {{ address.pincode }}<br>
</p>
{% endif %}
{% endmacro %}

{% set bns_settings = frappe.get_doc("BNS Settings", "BNS Settings") %}
{% set company_cin = frappe.db.get_value("Company", doc.company, "bns_company_cin") %}
{% set msme_no = frappe.db.get_value("Company", doc.company, "bns_msme_no") %}
{% set msme_type = frappe.db.get_value("Company", doc.company, "bns_msme_type") %}
{% set fssai_no = frappe.db.get_value("Address", doc.company_address, "bns_fssai_license_no") %}
<!--<div class="watermark text-center">MEVABITE</div>-->

<!--<div class="page">-->


<div id="header-html">
    <div class="row print-heading" style="line-height:1.1;padding:10px">
        <div class="col-xs-3 column-break bns-logo">
            {% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
            {% if company_logo %}
            <img src="{{ company_logo }}">
            {% endif %}
        </div>
        <div class="col-xs-6 column-break text-center">
            <h3 style="margin-top:0; margin-bottom:0;"><b>{{ doc.company }}</b></h3>
            {% if frappe.db.get_value("Company",doc.company,"bns_previously_known_as") %}
                <div style="font-size:0.85em;">Previously Known As: {{frappe.db.get_value("Company",doc.company,"bns_previously_known_as")}}</div>
            {% endif %}
            <div style="font-size:1em">
                {% set seller_address = frappe.db.get_value("Address", doc.company_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
                    {{ format_address(seller_address) }}
                    {% if company_cin %}
                    <span style="font-size:0.95em;">CIN: {{ company_cin }}</span><br>
                    {% endif %}
                    {% if msme_no %}
                    <span style="font-size:0.95em;">MSME No.: {{ msme_no }}</span>
                    {% if msme_type %}
                    <span style="font-size:0.95em;"> | MSME Type: {{ msme_type }}</span>
                    {% endif %}
                    <br>
                    {% endif %}
                    {% if doc.company_gstin %}
                    <span style="font-size:0.95em;"><b>GST:</b> {{ doc.company_gstin }}</span> | 
                    {% endif %}
                    <span style="font-size:0.95em;">PAN: {{ frappe.db.get_value("Company", doc.company, "pan") }}</span><br>
                    {% if fssai_no %}
                    <span style="font-size:0.95em;"><b>FSSAI No.:</b> {{ fssai_no }}</span><br>
                    {% endif %}

            </div>
        </div>
        <div class="col-xs-3 column-break text-right">
            <h2 class="bns-doc-title"><b>
                        {% if doc.is_return %}
                        Delivery Note Return
                        {% else %}
                        {% if doc.status == "Draft" %}
                        Draft Delivery Note
                        {% elif doc.status == "Cancelled" %}
                        Cancelled Delivery Note
                        {% else %}
                        Delivery Note
                        {% endif %}
                        {% endif %}
                    </b>
                </h2>
            {# Tally-style identity box: small label over a bold value. #}
            <div class="invoice-meta">
              <table class="bns-inv-id">
                <tr><td><div class="bns-inv-label">{{ "Return No." if doc.is_return else "DN No." }}</div><div class="bns-inv-value">{{ doc.name }}</div></td></tr>
                <tr><td><div class="bns-inv-label">Dated</div><div class="bns-inv-value">{{ frappe.utils.formatdate(doc.posting_date) }}</div></td></tr>
                {% if doc.place_of_supply %}
                <tr><td><div class="bns-inv-label">Place of Supply</div><div class="bns-inv-value bns-inv-small">{{ doc.place_of_supply }}</div></td></tr>
                {% endif %}
              </table>
            </div>
        </div>
    </div>
</div>

{% set fill = get_tally_fill_plan(doc, "BNS DN Dynamic V1") %}
{% if fill.measure %}<div class="bns-mk">BNSMKS</div>{% endif %}

        <!--<h5 class="section-heading">2. Party Details</h5>-->
        <!--<div class="section-break info-section">-->
        <div class="center-table">
            <table class="table table-bordered party-details-table">
                <tbody>
                    <tr>
                        <td colspan=6 rowspan=5>
                            {% set contact_person = frappe.db.get_value(
                        "Contact", doc.contact_person, ("mobile_no"), as_dict=True
                    ) %}
                            <h6><b><u>Buyer Details</u></b></h6>
                            <p><b>{{ doc.customer_name }}</b></p>
                            {% set customer_address = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city", "state", "pincode", "country","gstin"], as_dict=True) %}
                            {{ format_address(customer_address) }}

                            {% if doc.billing_address_gstin %}
                            GST: <u>{{ doc.billing_address_gstin }}</u><br>
                            {% endif %}
                            {% set customer_pan = frappe.db.get_value("Customer", doc.customer_name, "pan")%}
                            {% if customer_pan %}
                            PAN: {{ customer_pan }}<br>
                            {% endif %}
                            {% if contact_person.mobile_no %}
                            Phone No: {{ contact_person.mobile_no }}
                            {% endif %}
                            {% if doc.shipping_address %}
                            <br><br>
                            <h6><b><u>Shipping Details</u></b></h6>
                            <p><b>{{ doc.shipping_address_name }}</b></p>
                            {% set shipping_address = frappe.db.get_value("Address", doc.shipping_address_name, ["address_line1", "address_line2", "city", "state", "pincode", "country","gstin"], as_dict=True) %}
                            {{ format_address(shipping_address) }}
                            {% if shipping_address.gstin %}
                            GST: <u>{{ shipping_address.gstin }}</u><br>
                            {% endif %}
                            {% endif %}
                            {% if doc.dispatch_address %}
                            <h6><b><u>Dispatch Details</u></b></h6>
                            <p><b>{{ frappe.db.get_value("Address", doc.dispatch_address_name, "address_title") }}</b></p>
                            <!--<p>{{doc.dispatch_address}}</p>-->
                            {% set dispatch_address = frappe.db.get_value("Address", doc.dispatch_address_name, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
                            {{ format_address(dispatch_address) }}
                            {% endif %}
                        </td>
                        <td colspan=3>
                            <h6>Transporter:</h6>
                            {% if doc.transporter_name %}
                            {{ doc.transporter_name }} <br>
                            {{ doc.gst_transporter_id }}
                            {% else %}<br>{% endif %}
                        </td>
                        <td colspan=3>
                            <h6>Vehicle No:</h6>
                            {% if doc.vehicle_no %}
                            {{ doc.vehicle_no }}
                            {% else %}<br>{% endif %}
                        </td>
                    </tr>
                    <tr>
                        <td colspan=3>
                            <h6>Buyer's PO No:</h6>
                            {% if doc.po_no %}
                            {{ doc.po_no }}
                            {% else %}<br>{% endif %}
                        </td>
                        <td colspan=3>
                            <h6>PO Date:</h6>
                            {% if doc.po_date %}
                            {{ doc.po_date }}
                            {% else %}<br>{% endif %}
                        </td>
                    </tr>
                    <tr>
                        <td colspan=3>
                            {% if doc.ewaybill %}
                            <h6>e-Waybill No:</h6>
                            {{ doc.ewaybill }}
                            {% endif %}
                            <h6>Builty No:</h6>
                            {% if doc.custom_builty_no %}
                            {{ doc.custom_builty_no }}
                            {% else %}<br>{% endif %}
                        </td>
                        <td colspan=3>
                            <h6>Remarks:</h6>
                            {% if doc.remarks %}
                            {{ doc.remarks }}
                            {% else %}<br>{% endif %}
                        </td>
                    </tr>
                    {% if doc.incoterm or doc.named_place  %}
                    <tr>
                        <td colspan=3>
                            <h6>Incoterm:</h6>
                            {% if doc.incoterm %}
                            {{ doc.incoterm }}
                            {% else %}<br>{% endif %}
                        </td>
                        <td colspan=3>
                            <h6>Named Place:</h6>
                            {% if doc.named_place %}
                            {{ doc.named_place }}
                            {% else %}<br>{% endif %}
                        </td>
                    </tr>
                    {% endif %}
                    <tr>
                        <td colspan=2>

                            <h6>Destination:</h6>
                            {% if doc.custom_destination %}
                            {{doc.custom_destination}}
                            {% else %}<br>{% endif %}
                        </td>
                        <td rowspan=2 colspan=4>
                            <h6>Terms of Delivery:</h6>
                            {% if doc.custom_terms_of_delivery %}
                            {{ doc.custom_terms_of_delivery }}
                            {% elif doc.custom_terms_of_delivery_new %}
                            {{ doc.custom_terms_of_delivery_new }}
                            {% else %}<br><br>{% endif %}
                        </td>
                    </tr>
                    <tr>
                        <td colspan=2 rowspan=1>
                            <h6>Doc No:</h6>
                            {% if doc.custom_doc_no %}
                            {{doc.custom_doc_no}}
                            {% else %}<br>{% endif %}
                        </td>
                    </tr>
                </tbody>
            </table>
        </div>

        <!--<p></p>-->

        <!--</div>-->
        <div class="item-det">
            {% if fill.measure %}<div class="bns-mk">BNSMKT</div>{% endif %}
            <table class="table table-bordered e-invoice-table">
            <thead>
                <tr>
                    <th colspan="2">#</th>
                    <th colspan="31">Item</th>
                    <th colspan="7">Qty</th>
                    {% if bns_settings.rate_incl_tax %}
                    <th colspan="9">Rate(Inc Tax)</th>
                    {% endif %}
                    {% if bns_settings.rate_excl_tax %}
                    <th colspan="9">Rate(Exc Tax)</th>
                    {% endif %}
                    {% if bns_settings.discount_type == "Triple Compounded" %}
                    <th colspan="4">D1</th>
                    <th colspan="4">D2</th>
                    <th colspan="4">D3</th>
                    {% else %}
                    <th colspan="4">Disc</th>
                    {% endif %}
                    <th colspan="11">Net Total</th>
                </tr>
            </thead>

                <tbody>
                    {% for item in doc.items %}
                    <tr class="no-break">
                        <td colspan="2">{% if fill.measure and loop.first %}<div class="bns-mk">BNSMKH</div>{% endif %}{{ loop.index }}</td>
                        <td colspan="31" class="item-det-item-name">
                            {# Same item cell as the Sales Invoice: name, then HSN/SAC and EAN in the same cell. #}
                            <b>{{ item.item_name }}</b><br>
                            <p class="bns-item-sub"><i>
                            {% if item.gst_hsn_code %}<b>HSN/SAC: </b>{{ item.gst_hsn_code }}{% endif %}
                            {% if item.get("barcode") %}{% if item.gst_hsn_code %} | {% endif %}<b>EAN:</b> {{ item.barcode }}{% endif %}
                            </i></p>
                        </td>
                        <td colspan="7" class="text-left" style="line-height: 95%;">
                            <b>
                                {{ item.qty }} {{ item.uom }}
                                {% if bns_settings.secondary_rate_display %}
                                    {% if bns_settings.secondary_rate_field == "print_uom" %}
                                        {% set print_uom = frappe.db.get_value("Item", item.item_code, "custom_print_uom") %}
                                        {% if print_uom and item.uom != print_uom %}
                                            {% set print_uom_conversion = frappe.db.get_value(
                                                "UOM Conversion Detail",
                                                {"parent": item.item_code, "uom": print_uom},
                                                "conversion_factor"
                                            ) %}
                                            <br>
                                            <small style="font-size:0.35rem;">{{ (item.conversion_factor / print_uom_conversion) | int }} {{ print_uom }}/{{ item.uom }}</small>
                                        {% endif %}
                                    {% elif bns_settings.secondary_rate_field == "weight_uom" and item.total_weight != 0 %}
                                        {% if item.weight_uom == "Kg" and item.weight_uom != item.uom %}
                                            <br>
                                            <small style="font-size:0.6rem;">{{ item.total_weight }} Kg</small>
                                        {% elif item.weight_uom == "Gram" and item.weight_uom != "Kg" and item.weight_uom != "Gram" %}
                                            <br>
                                            <small style="font-size:0.6rem;">{{ item.total_weight / 1000 }} Kg</small>
                                        {% endif %}
                                    {% endif %}
                                {% endif %}
                            </b>
                        </td>
                        {% if doc.taxes and doc.taxes|length > 0 %}
                            {% if doc.taxes[0].included_in_print_rate == 1 %}

